package com.print.kiosk.scheduler; import com.print.kiosk.service.interfaces.FileCleanupService;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component public class FileCleanupScheduler{private final FileCleanupService service;public FileCleanupScheduler(FileCleanupService s){service=s;}@Scheduled(fixedDelayString="${app.print-request.file-cleanup-scan-ms:60000}")public void run(){service.deleteEligibleFileContent();}}
